    "purpose": "Bu dersin amacı Yüksek Lisans ve Doktora öğrencilerine Optoelektronik devre elemanları hakkında öğrencilere bilgi kazandırarak yüksek lisans ve doktora çalışmalarına yardımcı olmaktır.",
    "content": "Optoelektroniğe giriş, optik ışınlar, optoelektronik devreler, LED’ler, lazerler, ışın vericiler ve foto alıcılar",
    "methods": "Anlatım",
    "resources": "Kaynaklar: A. Erol, N. Balkan, Yarıiletkenler ve Optoelektronik Uygulamaları, Ocak 2015/2. BaskıVarol, H. S. (2018). Optoelektronik ve fiber optik. Nobel Akademik Yayıncılık.Wilson, J., & Hawkes, J. F. B. (2000). Optoelektronik (Çev. İ. Okur). Değişim Yayınları.; Ders Notları: A. Erol, N. Balkan, Yarıiletkenler ve Optoelektronik Uygulamaları, Ocak 2015/2. Baskı",
