      "Yarı iletken fiziği için sürdürülebilir bir uygulama yaklaşımı geliştirir.",
      "Yarı iletken fiziği faaliyetlerindeki etkileri ve riskleri değerlendirir.",
      "Yarı iletken fiziği bulgularını etik ve bilimsel ölçütlerle yorumlar."
