      "Enerji bantlarının oluşumu, enerji seviyesi diyagramları",
      "Safsızlık seviyeli yarıiletkenler",
      "P-n eklem yapısı",
      "Yarıiletken aygıt temelleri: kapsam ve temel kavramlar",
