      "Galaksiler ve Karanlık Madde: Kozmosun Büyük Ölçekli Yapısı Kozmoloji: Büyük Patlama ve Evrenin Kaderi Erken Evren: Zamanın Başlangıcına Doğru Evrendeki Yaşam: Yalnız mıyız?",
      "Kopernik DevrimiModern Bilimin Doğuşu Antik Astronomi Yermerkezli Evren Güneş Sisteminin Helyosentrik Modeli",
      "Kopernik Devriminin Temelleri Modern Astronominin Doğuşu Gezegen Hareket Kanunları",
      "Gezegen Yörüngelerinin Bazı Özellikleri Güneş Sisteminin Boyutları",
      "H-R Diyagramları",
      "Yıldız Yaş Tayinleri Ve Uygulamalar",
      "Astronomiye giriş: kapsam ve temel kavramlar",
      "Gök koordinatları ve gözlemsel veriler"
