    "purpose": "Bu dersin amacı, parçacık difüzyon kuramının temel ilkelerini yüksek lisans düzeyinde inceleyerek, öğrencilerin temel difüzyon denklemlerini formüle etme, çözme ve uygulama yeteneği kazanmasını sağlamaktır.",
    "content": "Difüzyon denklemleri, sınır ve başlangıç koşulları, tek boyutlu ve çok boyutlu çözümler, kaynak terimleri, analitik ve sayısal yöntemler, uygulamalar ve problemler. Diffusion equations, boundary and initial conditions, one-dimensional and multi-dimensional solutions, source terms, analytical and numerical methods, applications and problems.",
    "methods": "- Anlatım (teorik ders)-Matematiksel modelleme ve türetme çalışmaları- Tartışma ve etkileşimli değerlendirme-Soru–Cevap",
    "resources": "Kaynaklar: Bell, G. I., Glasstone, S., Nuclear Reactor Theory - Diffusion ChaptersLamarsh, J. R., & Baratta, A. J. Introduction to Nuclear EngineeringStacey, W. M. Nuclear Reactor Physics; Ders Notları: Bell, G. I., Glasstone, S., Nuclear Reactor Theory - Diffusion Chapters2. Duderstadt, J. J., Hamilton, L. J., Nuclear Reactor Analysis - Diffusion Sections3. Lamarsh, J. R., Introduction to Nuclear Reactor Theory; Dökümanlar: Stacey, W. M. Nuclear Reactor Physics",
    "sdgs": [
      "3",
      "7",
      "9"
    ],
    "outcomes": [
      "Parçacık difüzyon kuramı ı kapsamındaki temel ve ileri yaklaşımları analiz eder.",
      "Nükleer fizik ve radyasyon alanındaki uygulamaları karşılaştırır.",
      "Parçacık difüzyon kuramı ı için sürdürülebilir bir uygulama yaklaşımı geliştirir.",
      "Parçacık difüzyon kuramı ı faaliyetlerindeki etkileri ve riskleri değerlendirir.",
      "Parçacık difüzyon kuramı ı bulgularını etik ve bilimsel ölçütlerle yorumlar."
    ],
    "weeklyTopics": [
      "Giriş ve temel difüzyon kavramları",
      "Tek boyutlu difüzyon denklemleri",
      "Çok boyutlu çözümler",
      "Sınır ve başlangıç koşulları",
      "Kaynak terimleri ve uygulamalar",
      "Analitik çözümler",
      "Sayısal çözümler",
      "Nötron transport teoride difüzyon yaklaşımı",
      "Difüzyon problemlerinde uygulamalar",
      "Parçacık akısı ve yoğunluğu hesaplamaları",
      "Difüzyon kuramının enerji bağımlı uygulamaları",
      "Güvenlik ve kontrol uygulamaları",
      "Karmaşık difüzyon problemleri ve simülasyonlar",
      "Parçacık difüzyon kuramına yapay zeka yaklaşımı",
      "Parçacık difüzyon kuramı ı: kapsam ve temel kavramlar"
    ],
