      "Optik Aletler",
      "Kamera, Odak, Poz süresi kontrolü Kontrolü",
      "Astronomik Teleskop, yersel Teleskop,",
      "Oküler ve Okülerler, Optik Aletlerde Kusurlar Ders Notları Kitanın Bölümü",
      "Kromatik Sapma, Küresel Aberasyon",
      "İnterferometreler, Çoklu Işın Paraziti, Parazit Filtreleri",
      "Tek Yarıkta ve çift yarıkta Kırınım Deseninin Matematiksel Formülasyonu",
      "Kırınım ağı , Kırınım ağının Çözme Gücü, Fabry-Perot, İnterferometre, etalonlar",
      "Optik ve optik ölçme metotları: kapsam ve temel kavramlar"
