    "content": "Nötron fiziği ve nükleer reaktörlerin temel çalışma prensipleri.",
    "methods": "Anlatım, soru cevap, ödev",
    "resources": "Kaynaklar: Lilley,John Aydın, Abdullah (çeviri editörü.), Sarpün, İsmail Hakkı (çeviri editörü.), Tel, Eyyup (çeviri editörü.), Kaplan, Abdullah (çeviri editörü.); Ders Notları: Nükleer Reaktör Fiziğinin Temelleri-Editör E. E. Lewis -Çeviri Editörü Songül AKBULUT ÖZEN Yayın Koordinatörü Yasin DİLMENSayfa ve Kapak TasarımıAkademisyen Dizgi Ünitesi",
