    "ects": 6,
    "prerequisites": "Yok",
    "instructor": "Prof. Dr. Eyyup TEL https://akbis.osmaniye.edu.tr/@eyuptel eyuptel@osmaniye.edu.tr",
    "purpose": "Radyasyonların fiziksel özellikleri ve biyolojik etkileri ile ilgili bilginin kazandırılması, iç ve dış radyasyon kaynaklarından canlı dokulara aktarılan dozların hesaplanma yöntemlerinin öğretilmesi, radyasyondan korunma kültürünün ( ALARA kültürü) kazandırılması.",
    "content": "Radyasyonlardan Korunma İlkeleri, Radyasyon Doz Hesaplamaları, Radyasyonların Biyolojik Etkileri, Risk değerlendirmesi, Medikal uygulamalar, Halk Sağlığı.",
    "methods": "Yüz yüze",
    "resources": "Kaynaklar: Radiation Protection in Medical Physics, Yves Lemoigne, Alessandra Caner, Springer, 2009.Radiation protection: a guide for scientists, regulators, and physicians, (Fourth Edition), Jacop Shapiro, Harvard University Press, 2002.Introduction to Health Physics: Fourth Edition, Herman Cember, Thomas Edward Johnson, McGraw Hill, 2009.Radiation protection and dosimetry: an introduction to health physics, Michael G. Stabin, Springer, 2007.Atoms, Radiation, and Radiation Protection, James Edward Turner, Wiley-VCH, 2007.Physics for radiation protection, James E. Martin ,John Wiley & Sons, 2000.ICRP, IAEA Publications; Ders Notları: Radiation protection: a guide for scientists, regulators, and physicians, (Fourth Edition), Jacop Shapiro, Harvard University Press, 2002.",
