      "termonükleer tesir kesit",
      "nükleer astrofizikte yavaş ve hızlı süreçler",
      "yüksek enerji fiziğindeki nükleer çarpışmalar",
      "yüksek enerji fiziğindeki nükleer saçılmalar",
      "Nükleer reaksiyonlar ıı: kapsam ve temel kavramlar"
