    "content": "Nötron transport denkleminin türetilmesi, nötron saçılma fonksiyonu, tek-hızlı transport denklemi, Değişkenlerine ayırma yöntemi, Fourier transformu yöntemi, Küresel harmonikler yöntemi, Birinci ve ikinci tip Chebyshev polinomları (TN ve UN) yöntemleri, Diskret ordinatlar (SN) yöntemi.",
