    "purpose": "nükleer bozunma ve radyaoaktiflik hakkında bilgi vermektir",
    "content": "Öğretim Yöntem ve Teknikleri:Radyoaktif bozunma kanunu, Işımalı bozunmaların kuantum teorisi, radyoaktifliğin üretilmesi ve bozunumu, ürün aktivitelerinin çoğalması, bozunma türleri, doğal radyoaktiflik,radyoaktif yaş tayini, radyasyon ölçü birimleri, gama bozunumu ve iç dönüşüm, radyasyonun madde ile etkileşimi, sintilatör detektörler, yarı iletken detektörler",
    "methods": "Kuramsal anlatım, kaynak ve metin çözümlemesi, karşılaştırmalı tartışma ve araştırma bulgularının değerlendirilmesi.",
    "resources": "Kaynaklar: 2009, Raymond L. Murray and Keith E. Holbert,Nuclear Physics: Principles and Application John Lilley. ISBN: 978-0-471-97936-4 June 2001 412 Pages; Ders Notları: Introduction to Nuclear Engineering, John R. Lamarsh, Anthony J. Baratta:,Pearson Education. ISBN, : 9780132764575,Introductory Nuclear",
