    "purpose": "Bu dersin amacı: Yüksek lisans ve Doktora Öğrencilerine “Metal-Yarıiletkenlerin Elektriksel Özellikleri” hakkında derinlemesine bilgi kazandırarak yüksek lisans ve doktora çalışmalarına yardımcı olmaktır",
    "content": "Metal-Yarıiletkenlerin elektriksel özellikler hakkında genel bilgi. Yarıiletkenlerin temel kavramlarını anlamak, Yarıiletken fiziğinin bazı önemli terimleri ve yöntemleri kavramak, taşıyıcı iletimi fenomeninin temellerini öğrenmek, Metel-Yarıiletken malzemelerin özelliklerinin analizini öğrenmek",
    "methods": "Anlatım",
    "resources": "Kaynaklar: Physics of Semiconductor Devices (Jean-Pierre Collinge, C.A Colinge /Yarıiletken Devre Elemanları Fiziği). Ç. Editörleri: S. TÜZEMEN, S.TEKMENColinge, J.-P., & Colinge, C. A. (2011). Yarıiletken devre elemanları fiziği (Physics of semiconductor devices) (S. Tüzemen & S. Tekmen, Çev.). Ankara: Nobel Akademik Yayıncılık.Neamen, D. A. (2010). Yarıiletken fiziği (Çev. baskı). İstanbul: Aktif Yayınevi.; Ders Notları: 1. Physics of Semiconductor Devices (Jean-Pierre Collinge, C.A Colinge /Yarıiletken Devre Elemanları Fiziği). Ç. Editörleri: S. TÜZEMEN, S.TEKMEN2. Yarıiletken Fiziği(K.Seeger)",
