      "İnsan Beyni, Bir Nöron Modelleri",
      "Basit Nöronlar ve Ağlar",
      "Yapay Zeka ve Sinir Ağları",
      "İstatistiğe giriş ve İstatistiksel Yaklaşım",
      "Ağ Mimarileri",
      "Modeller, genel yapay sinir hücre modeli",
      "Yönlendirilmiş Grafikler Olarak Görüntülenen Sinir Ağları",
      "Matlab’a Giriş. Matlab’da İfadeler ve İşlemler.",
      "Matlab’da Diziler ( Vektör,Matris ve Polinomlar), Matlab'de Matematik ve Kod Eşdeğerleri",
      "Denklemler ve Şekiller için Matematiksel Gösterim, Matlab",
      "Yapay sinir ağları ile allık olarak yıllık güneş enerjisi tahmini",
      "Uygulamalar",
      "Yapay sinir ağlatı ve uygulamaları ıı: kapsam ve temel kavramlar"
