      "Örten Değişen Çift Yıldızlar : Gözlemler, Yörünge Parametreleri ve Genel Özellikleri, Işık eğrisi, yörünge knumları ve minimum tanımları, ilginç sistemlere örnekler",
      "PHOEBE programına giriş I",
