    "content": "Süperiletkenliğin ortaya çıkışı, Süperiletkenliğin termodinamiği, Entropi, Londondenklemleri, Süperiletkenlerin lokal olmayan elektrodinamiği, Girzburg-Landau teorisi ve II. Tipsüperiletkenler, Manyetik akının kuantumlanması, Kritik durum-Bean modeli, Süperiletkenliğin elektronfonon mekanizması, BCS Teorisi, Eliashberg teorisi, Josephson olayı, Yüksek sıcaklık süperiletkenleri.",
