      "Katıhal ve malzeme fiziği alanındaki uygulamaları karşılaştırır.",
      "Süperiletken fiziğine giriş ıı için sürdürülebilir bir uygulama yaklaşımı geliştirir.",
      "Süperiletken fiziğine giriş ıı faaliyetlerindeki etkileri ve riskleri değerlendirir.",
