    "content": "Katıların Isıl ve Optik özellikleri; Serbest Elektron Modeli. Metallerde Isıl ve Elektriksel İletkenlik; Katılarda Enerji Bantları: Bloch Teoremi, Katıların elektriksel özellikleri, Metallerin Bant Yapıları, Yalıtkanlar ve Yarı İletkenler, Enerji Bantlarının Hesaplanması, Bant Yapısının Deneysel Yöntemlerle Belirlenmesi; Yarı iletkenler ve yarı iletken aygıtlar.",
